function rumorHolders(n: number, delay: number, forget: number): number {
  const MOD = 1000000007;
  const fresh = new Array(n + 1).fill(0);
  fresh[1] = 1;
  let sharing = 0;
  for (let d = 2; d <= n; d++) {
    if (d - delay >= 1) sharing = (sharing + fresh[d - delay]) % MOD;
    if (d - forget >= 1) sharing = (sharing - fresh[d - forget] + MOD) % MOD;
    fresh[d] = sharing;
  }
  let total = 0;
  for (let d = Math.max(1, n - forget + 1); d <= n; d++) total = (total + fresh[d]) % MOD;
  return total;
}

